import torch
import torch.nn as nn
from torch.nn.modules.utils import _triple
from torch.utils.cpp_extension import load_inline


_cuda_src = r'''
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>
#include <cuda.h>
#include <cuda_runtime.h>

__device__ __forceinline__ int floor_div_int(const int a, const int b) {
    return a >= 0 ? a / b : -(((-a) + b - 1) / b);
}

__global__ void conv_transpose3d_kernel(
    const float* __restrict__ x,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ out,
    int N, int IC, int ID, int IH, int IW,
    int OC, int OD, int OH, int OW,
    int KD, int KH, int KW,
    int stride_d, int stride_h, int stride_w,
    int pad_d, int pad_h, int pad_w,
    int dil_d, int dil_h, int dil_w,
    int groups,
    int IC_per_group,
    int OC_per_group,
    int tile_h,
    int tile_w)
{
    extern __shared__ float smem[];
    constexpr int OC_TILE = 4;

    const int tx = static_cast<int>(threadIdx.x);
    const int ty = static_cast<int>(threadIdx.y);
    const int tid = ty * blockDim.x + tx;
    const int ox0 = static_cast<int>(blockIdx.x) * blockDim.x;
    const int oy0 = static_cast<int>(blockIdx.y) * blockDim.y;
    const int ox = ox0 + tx;
    const int oy = oy0 + ty;

    const int z = static_cast<int>(blockIdx.z);
    const int oz = z % OD;
    const int oc_tiles_per_group = (OC_per_group + OC_TILE - 1) / OC_TILE;
    const int tile_id = z / OD;
    const int n = tile_id / (groups * oc_tiles_per_group);
    const int group_tile = tile_id % (groups * oc_tiles_per_group);
    const int group = group_tile / oc_tiles_per_group;
    const int oc_tile = group_tile % oc_tiles_per_group;
    const int oc_base = oc_tile * OC_TILE;

    const int base_y = floor_div_int(
        oy0 + pad_h - (KH - 1) * dil_h, stride_h);
    const int base_x = floor_div_int(
        ox0 + pad_w - (KW - 1) * dil_w, stride_w);

    const int smem_elems = IC_per_group * tile_h * tile_w;
    const bool active = ox < OW && oy < OH && n < N;

    float acc[OC_TILE];
    for (int q = 0; q < OC_TILE; ++q) {
        const int oc_local = oc_base + q;
        acc[q] = (active && bias != nullptr && oc_local < OC_per_group)
            ? bias[group * OC_per_group + oc_local]
            : 0.0f;
    }

    for (int kz = 0; kz < KD; ++kz) {
        for (int linear = tid; linear < smem_elems;
             linear += blockDim.x * blockDim.y) {
            int t = linear;
            const int sx = t % tile_w;
            t /= tile_w;
            const int sy = t % tile_h;
            t /= tile_h;
            const int ic_local = t;

            const int tz = oz + pad_d - kz * dil_d;
            const bool valid_z =
                tz >= 0 && (tz % stride_d) == 0 && (tz / stride_d) < ID;
            const int iz = tz / stride_d;
            const int iy = base_y + sy;
            const int ix = base_x + sx;
            const bool valid_xy =
                iy >= 0 && iy < IH && ix >= 0 && ix < IW;

            float value = 0.0f;
            if (valid_z && valid_xy && n < N) {
                const int ic = group * IC_per_group + ic_local;
                const int64_t x_idx =
                    (((static_cast<int64_t>(n) * IC + ic) * ID + iz) * IH + iy) * IW + ix;
                value = x[x_idx];
            }
            smem[(ic_local * tile_h + sy) * tile_w + sx] = value;
        }
        __syncthreads();

        if (active) {
            const int tz = oz + pad_d - kz * dil_d;
            if (tz >= 0 && (tz % stride_d) == 0) {
                const int iz = tz / stride_d;
                if (iz >= 0 && iz < ID) {
                    for (int ky = 0; ky < KH; ++ky) {
                        const int ty_in = oy + pad_h - ky * dil_h;
                        if (ty_in < 0 || (ty_in % stride_h) != 0) {
                            continue;
                        }
                        const int iy = ty_in / stride_h;
                        if (iy < 0 || iy >= IH) {
                            continue;
                        }
                        const int sy = iy - base_y;

                        for (int kx = 0; kx < KW; ++kx) {
                            const int tx_in = ox + pad_w - kx * dil_w;
                            if (tx_in < 0 || (tx_in % stride_w) != 0) {
                                continue;
                            }
                            const int ix = tx_in / stride_w;
                            if (ix < 0 || ix >= IW) {
                                continue;
                            }
                            const int sx = ix - base_x;
                            if (sy < 0 || sy >= tile_h || sx < 0 || sx >= tile_w) {
                                continue;
                            }

                            for (int ic_local = 0; ic_local < IC_per_group; ++ic_local) {
                                const int ic = group * IC_per_group + ic_local;
                                const float input_value =
                                    smem[(ic_local * tile_h + sy) * tile_w + sx];
                                for (int q = 0; q < OC_TILE; ++q) {
                                    const int oc_local = oc_base + q;
                                    if (oc_local < OC_per_group) {
                                        const int64_t w_idx =
                                            ((((static_cast<int64_t>(ic) * OC_per_group + oc_local) * KD + kz)
                                              * KH + ky) * KW + kx);
                                        acc[q] += input_value * weight[w_idx];
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
        __syncthreads();
    }

    if (!active) {
        return;
    }

    for (int q = 0; q < OC_TILE; ++q) {
        const int oc_local = oc_base + q;
        if (oc_local < OC_per_group) {
            const int ocl = group * OC_per_group + oc_local;
            const int64_t out_idx =
                (((static_cast<int64_t>(n) * OC + ocl) * OD + oz) * OH + oy) * OW + ox;
            out[out_idx] = acc[q];
        }
    }
}

torch::Tensor conv_transpose3d_cuda(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    int64_t stride_d, int64_t stride_h, int64_t stride_w,
    int64_t pad_d, int64_t pad_h, int64_t pad_w,
    int64_t output_pad_d, int64_t output_pad_h, int64_t output_pad_w,
    int64_t dil_d, int64_t dil_h, int64_t dil_w,
    int64_t groups)
{
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be a CUDA tensor");
    TORCH_CHECK(!bias.defined() || bias.is_cuda(), "bias must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "only float32 tensors are supported");
    TORCH_CHECK(weight.scalar_type() == at::kFloat, "only float32 tensors are supported");
    TORCH_CHECK(!bias.defined() || bias.scalar_type() == at::kFloat,
                "only float32 tensors are supported");
    TORCH_CHECK(x.dim() == 5, "x must have shape (N, C, D, H, W)");
    TORCH_CHECK(weight.dim() == 5, "weight must have shape (IC, OC/groups, KD, KH, KW)");

    auto x_contig = x.contiguous();
    auto weight_contig = weight.contiguous();
    torch::Tensor bias_contig;
    if (bias.defined()) {
        bias_contig = bias.contiguous();
    }

    const int N = static_cast<int>(x_contig.size(0));
    const int IC = static_cast<int>(x_contig.size(1));
    const int ID = static_cast<int>(x_contig.size(2));
    const int IH = static_cast<int>(x_contig.size(3));
    const int IW = static_cast<int>(x_contig.size(4));

    const int OC = static_cast<int>(weight_contig.size(1) * groups);
    const int KD = static_cast<int>(weight_contig.size(2));
    const int KH = static_cast<int>(weight_contig.size(3));
    const int KW = static_cast<int>(weight_contig.size(4));

    const int OD = static_cast<int>(
        (ID - 1) * stride_d - 2 * pad_d + dil_d * (KD - 1) + output_pad_d + 1);
    const int OH = static_cast<int>(
        (IH - 1) * stride_h - 2 * pad_h + dil_h * (KH - 1) + output_pad_h + 1);
    const int OW = static_cast<int>(
        (IW - 1) * stride_w - 2 * pad_w + dil_w * (KW - 1) + output_pad_w + 1);

    TORCH_CHECK(groups > 0, "groups must be positive");
    TORCH_CHECK(IC % groups == 0, "input channels must be divisible by groups");
    TORCH_CHECK(OC % groups == 0, "output channels must be divisible by groups");
    TORCH_CHECK(weight_contig.size(0) == IC,
                "weight.size(0) must equal input channels");
    TORCH_CHECK(!bias.defined() || bias.numel() == 0 ||
                bias_contig.numel() == OC,
                "bias must have exactly OC elements");
    TORCH_CHECK(OD > 0 && OH > 0 && OW > 0,
                "computed output dimensions must be positive");
    auto out = torch::empty({N, OC, OD, OH, OW}, x_contig.options());

    at::cuda::CUDAGuard device_guard(x_contig.device());
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    const int IC_per_group = IC / static_cast<int>(groups);
    const int OC_per_group = OC / static_cast<int>(groups);
    const int oc_tiles_per_group = (OC_per_group + 4 - 1) / 4;
    const dim3 block(8, 4, 1);
    const dim3 grid(
        (OW + block.x - 1) / block.x,
        (OH + block.y - 1) / block.y,
        N * groups * oc_tiles_per_group * OD);
    const int block_h = static_cast<int>(block.y);
    const int block_w = static_cast<int>(block.x);
    const int tile_h =
        (block_h - 1 + (KH - 1) * static_cast<int>(dil_h)) /
        static_cast<int>(stride_h) + 2;
    const int tile_w =
        (block_w - 1 + (KW - 1) * static_cast<int>(dil_w)) /
        static_cast<int>(stride_w) + 2;
    const size_t smem_bytes =
        static_cast<size_t>(IC_per_group) *
        static_cast<size_t>(tile_h) *
        static_cast<size_t>(tile_w) *
        sizeof(float);
    conv_transpose3d_kernel<<<grid, block, smem_bytes, stream>>> (
        x_contig.data_ptr<float>(),
        weight_contig.data_ptr<float>(),
        bias.defined() && bias.numel() > 0
            ? bias_contig.data_ptr<float>()
            : nullptr,
        out.data_ptr<float>(),
        N, IC, ID, IH, IW,
        OC, OD, OH, OW,
        KD, KH, KW,
        static_cast<int>(stride_d),
        static_cast<int>(stride_h),
        static_cast<int>(stride_w),
        static_cast<int>(pad_d),
        static_cast<int>(pad_h),
        static_cast<int>(pad_w),
        static_cast<int>(dil_d),
        static_cast<int>(dil_h),
        static_cast<int>(dil_w),
        static_cast<int>(groups),
        IC_per_group,
        OC_per_group,
        tile_h,
        tile_w);
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return out;
    return out;
}
